def bind_worker_occupancy(
    batch,
    *,
    negotiated_tokens: list,
    plan_id: str,
    execution_plan: dict,
    stage_specs: dict,
    closures: dict,
    views: dict,
    minted_by_ordinal: dict,
    inventories: list,
    enumeration_plan: dict,
